def transform(grid):
    # The grid contains scattered noise pixels (colors other than 1 and 8) and two main objects (1s and 8s).
    # The task is to filter out the noise while preserving the 1s and 8s.
    # All other cells are set to 0 (background).

    result = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == 1 or cell == 8:
                new_row.append(cell)
            else:
                new_row.append(0)
        result.append(new_row)
    return result
